    <GlassPlate sx={{ p: .8, minWidth: 0, display: 'grid', gridTemplateRows: 'auto minmax(0,1fr)' }}><Box sx={{ display: 'flex', justifyContent: 'space-between' }}><Typography sx={{ fontSize: 9, color: C.faint }}>{tr(locale, '24h trace', 'روند ۲۴ ساعت')}</Typography><Typography sx={{ fontSize: 9, color: C.faint }}>MIN {Math.round(value * .87)} · MAX {Math.round(value * 1.11)}</Typography></Box><LuminousChart values={values} color={theme.accent} fill/></GlassPlate>
