    return <Box sx={{ height: '100%', display: 'grid', gridTemplateRows: 'auto auto minmax(0,1fr)', gap: 1, direction: 'ltr' }}><Box sx={{ display: 'flex', alignItems: 'end', justifyContent: 'space-between', gap: 1 }}><Box><Typography sx={{ fontSize: 46, fontWeight: 760, lineHeight: .86, letterSpacing: '-.06em' }}>{value}<Box component="span" sx={{ fontSize: 14, ml: .6, color: C.muted }}>{unit}</Box></Typography><Box sx={{ mt: .8 }}><StatusText color={trendColor}>{positive ? '↑' : '↓'} {Math.abs(trend)}% / 24h</StatusText></Box></Box><Box sx={{ display: 'grid', gridTemplateColumns: 'repeat(3,minmax(70px,1fr))', gap: .65, maxWidth: 300 }}><MiniStat label="MIN" value={`${Math.round(value * .87)} ${unit}`}/><MiniStat label="AVG" value={`${value} ${unit}`} accent/><MiniStat label="MAX" value={`${Math.round(value * 1.11)} ${unit}`}/></Box></Box><ScaleBar value={value} max={max} color={theme.accent}/><GlassPlate sx={{ p: .8, minHeight: 0 }}><LuminousChart values={values} color={theme.accent} fill dots/></GlassPlate></Box>;
